UPDATE a SET Bestand = m.Gezaehlt
FROM Artikel AS a JOIN Meldungen AS m ON m.ArtikelId = a.Id
WHERE m.Gezaehlt IS NOT NULL;

SELECT a.Id, COALESCE(m.Gezaehlt, a.Bestand),
       CASE WHEN m.Gezaehlt IS NULL THEN 'Bestand' ELSE 'gezaehlt' END
FROM Artikel AS a LEFT JOIN Meldungen AS m ON a.Id = m.ArtikelId;

SELECT MAX(s.Gesamt)
FROM (
    SELECT b.ArtikelId, SUM(b.Menge) AS Gesamt
    FROM (SELECT ArtikelId, Menge FROM Nord UNION ALL SELECT ArtikelId, Menge FROM Sued) AS b
    GROUP BY b.ArtikelId
) AS s;

